+      border-radius: 16px;
+      background: linear-gradient(180deg, #fff 0%, #fbfcff 100%);
+    }
+
+    .checkbox-row {
+      display: flex;
+      gap: 12px;
+      align-items: flex-start;
+    }
+
+    input[type="checkbox"] {
+      width: 1.125rem;
+      height: 1.125rem;
+      margin: 3px 0 0;
+      accent-color: var(--accent);
+      flex: none;
+    }
+
+    label {
+      display: block;
+      font-weight: 600;
+      line-height: 1.45;
+      cursor: pointer;
+    }
+
+    .required-mark {
+      color: var(--accent);
+    }
+
+    .helper-text {
+      margin: 6px 0 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+      line-height: 1.45;
+    }
+
+    .error-text {
+      margin: 8px 0 0;
+      color: var(--error);
+      font-size: 0.95rem;
+      line-height: 1.45;
+    }
+
+    .error-text[hidden] {
+      display: none;
+    }
+
+    .form-field.is-invalid {
+      border-color: color-mix(in srgb, var(--error) 30%, var(--border));
+      background: linear-gradient(180deg, #fff 0%, #fff8f8 100%);
+    }
+
+    .actions {
+      display: flex;
+      align-items: center;
+      gap: 14px;
+      flex-wrap: wrap;
