+
+    button:hover {
+      filter: brightness(1.03);
+    }
+
+    button:focus-visible,
+    input[type="checkbox"]:focus-visible {
+      outline: 3px solid color-mix(in srgb, var(--accent) 42%, white);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5em;
+      color: var(--accent);
+      font-weight: 600;
+    }
+
+    @media (max-width: 420px) {
