+      <h1 id="page-title">Terms of Use consent</h1>
+      <p class="subtitle">Review the agreement below and confirm before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field" id="consent-field">
+          <div class="checkbox-row">
+            <input
+              id="agree-terms"
+              name="agreeTerms"
+              type="checkbox"
+              required
+              aria-describedby="agree-help agree-error"
+            >
+            <div>
+              <label for="agree-terms">
+                I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
+              </label>
+              <p class="helper-text" id="agree-help">
+                Required to continue using the service.
+              </p>
+              <p class="error-text" id="agree-error" hidden>Error: You must agree to the Terms of Use.</p>
+            </div>
+          </div>
+        </div>
+
+        <div class="actions">
+          <button type="submit">Continue</button>
+          <p class="status" id="form-status" role="status" aria-live="polite"></p>
+        </div>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById("consent-form");
+    const checkbox = document.getElementById("agree-terms");
+    const field = document.getElementById("consent-field");
+    const error = document.getElementById("agree-error");
+    const status = document.getElementById("form-status");
+
+    function setInvalid(isInvalid) {
+      checkbox.setAttribute("aria-invalid", String(isInvalid));
+      field.classList.toggle("is-invalid", isInvalid);
+      error.hidden = !isInvalid;
+    }
+
+    checkbox.addEventListener("change", () => {
+      if (checkbox.checked) {
+        setInvalid(false);
+        status.textContent = "";
+      }
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      if (!checkbox.checked) {
+        setInvalid(true);
+        status.textContent = "";
+        checkbox.focus();
+        return;
+      }
+
+      setInvalid(false);
+      status.textContent = "Consent saved.";
+      form.reset();
+    });
+  </script>
+</body>
+</html>
*** End Patch
