      width: min(100%, 520px);
    }

    .card {
      background: var(--card);
      border: 1px solid rgba(41, 98, 255, 0.08);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(24px, 4vw, 36px);
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.5rem, 3vw, 2rem);
      line-height: 1.15;
      letter-spacing: -0.03em;
    }

    .subtitle {
      margin: 0 0 28px;
