    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      padding: 18px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: linear-gradient(180deg, #fff 0%, #fbfcff 100%);
    }

    .checkbox-row {
      display: flex;
      gap: 12px;
      align-items: flex-start;
    }

    input[type="checkbox"] {
      width: 1.125rem;
      height: 1.125rem;
