      background:
        radial-gradient(circle at top, #ffffff 0%, var(--bg) 46%, #eaf0fb 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    main {
      width: min(100%, 520px);
    }

    .card {
      background: var(--card);
      border: 1px solid rgba(41, 98, 255, 0.08);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(24px, 4vw, 36px);
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.5rem, 3vw, 2rem);
      line-height: 1.15;
      letter-spacing: -0.03em;
    }

    .subtitle {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.5;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      padding: 18px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: linear-gradient(180deg, #fff 0%, #fbfcff 100%);
    }

    .checkbox-row {
      display: flex;
      gap: 12px;
      align-items: flex-start;
    }

    input[type="checkbox"] {
      width: 1.125rem;
      height: 1.125rem;
      margin: 3px 0 0;
      accent-color: var(--accent);
      flex: none;
    }

    label {
      display: block;
      font-weight: 600;
      line-height: 1.45;
      cursor: pointer;
    }

    .required-mark {
      color: var(--accent);
    }

    .helper-text {
      margin: 6px 0 0;
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.45;
    }

    .error-text {
      margin: 8px 0 0;
      color: var(--error);
      font-size: 0.95rem;
      line-height: 1.45;
    }

    .error-text[hidden] {
      display: none;
    }

    .form-field.is-invalid {
      border-color: #e1a0a0;
      background: linear-gradient(180deg, #fff 0%, #fff8f8 100%);
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 14px;
      flex-wrap: wrap;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      background: #2458e6;
