 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Terms of Use Consent</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --card: #ffffff;
       --text: #172033;
       --muted: #4c5870;
       --border: #d9e2f0;
       --accent: #2458e6;
       --error: #c62828;
       --shadow: 0 18px 50px rgba(19, 34, 63, 0.12);
       --radius: 20px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, #ffffff 0%, var(--bg) 46%, #eaf0fb 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     main {
       width: min(100%, 520px);
     }

     .card {
       background: var(--card);
       border: 1px solid rgba(41, 98, 255, 0.08);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
       padding: clamp(24px, 4vw, 36px);
     }

     h1 {
       margin: 0 0 8px;
       font-size: clamp(1.5rem, 3vw, 2rem);
       line-height: 1.15;
       letter-spacing: -0.03em;
     }

     .subtitle {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.5;
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       padding: 18px;
       border: 1px solid var(--border);
       border-radius: 16px;
       background: #ffffff;
     }

     .checkbox-row {
       display: flex;
       gap: 12px;
       align-items: flex-start;
     }

     input[type="checkbox"] {
       width: 1.125rem;
       height: 1.125rem;
       margin: 3px 0 0;
       accent-color: var(--accent);
       flex: none;
     }

     label {
       display: block;
       font-weight: 600;
       line-height: 1.45;
       cursor: pointer;
     }

     .required-mark {
       color: var(--accent);
     }

     .helper-text {
       margin: 6px 0 0;
       color: var(--muted);
       font-size: 0.95rem;
       line-height: 1.45;
     }

     .error-text {
       margin: 8px 0 0;
       color: var(--error);
       font-size: 0.95rem;
       line-height: 1.45;
     }

     .error-text[hidden] {
       display: none;
     }

     .form-field.is-invalid {
       border-color: #e1a0a0;
       background: linear-gradient(180deg, #fff 0%, #fff8f8 100%);
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 14px;
       flex-wrap: wrap;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       background: #2458e6;
       color: #fff;
       padding: 0.9rem 1.35rem;
       font: inherit;
       font-weight: 700;
       letter-spacing: 0.01em;
       cursor: pointer;
       box-shadow: 0 10px 22px rgba(36, 88, 230, 0.24);
     }

     button:hover {
       background: #1d4ed8;
     }

     button:focus-visible,
     input[type="checkbox"]:focus-visible {
       outline: 3px solid #2458e6;
       outline-offset: 3px;
     }

     .status {
       min-height: 1.5em;
       color: #2458e6;
       font-weight: 600;
     }

     @media (max-width: 420px) {
       body {
         padding: 16px;
       }

       .form-field {
         padding: 16px;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Terms of Use consent</h1>
       <p class="subtitle">Review the agreement below and confirm before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field" id="consent-field">
           <div class="checkbox-row">
             <input
               id="agree-terms"
               name="agreeTerms"
               type="checkbox"
               required
               aria-describedby="agree-help agree-error"
             >
             <div>
               <label for="agree-terms">
                 I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
               </label>
               <p class="helper-text" id="agree-help">
                 Required to continue using the service.
               </p>
               <p class="error-text" id="agree-error" hidden>Error: You must agree to the Terms of Use.</p>
             </div>
           </div>
         </div>

         <div class="actions">
           <button type="submit">Continue</button>
           <p class="status" id="form-status" role="status" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("consent-form");
     const checkbox = document.getElementById("agree-terms");
     const field = document.getElementById("consent-field");
     const error = document.getElementById("agree-error");
     const status = document.getElementById("form-status");

     function setInvalid(isInvalid) {
       if (isInvalid) {
         checkbox.setAttribute("aria-invalid", "true");
       } else {
         checkbox.removeAttribute("aria-invalid");
       }
       field.classList.toggle("is-invalid", isInvalid);
       error.hidden = !isInvalid;
     }

     checkbox.addEventListener("change", () => {
       if (checkbox.checked) {
         setInvalid(false);
         status.textContent = "";
       }
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       if (!checkbox.checked) {
         setInvalid(true);
         status.textContent = "";
         checkbox.focus();
         return;
       }

       setInvalid(false);
       status.textContent = "Consent saved.";
       form.reset();
     });
   </script>
 </body>
 </html>

